{
 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "$id": "urn:semantic-schema-core:core:semantic-abstract-schema:v1",
 "$vocabulary": {
  "https://json-schema.org/draft/2020-12/vocab/core": true,
  "https://json-schema.org/draft/2020-12/vocab/applicator": true,
  "https://json-schema.org/draft/2020-12/vocab/unevaluated": true,
  "https://json-schema.org/draft/2020-12/vocab/validation": true,
  "https://json-schema.org/draft/2020-12/vocab/meta-data": true,
  "https://json-schema.org/draft/2020-12/vocab/format-annotation": true,
  "https://json-schema.org/draft/2020-12/vocab/content": true,
  "urn:semantic-schema-core:core:vocab:v1": true
 },
 "title": "Semantic Abstract Schema v1 の本体",
 "description": "Semantic Concrete Schema が従う契約の版 v1。Concrete は $schema にこの $id を書いて、使う版と作法の版を示す。Core の x- は9つで、根に x-instance-path ・ x-instance-label ・ x-delegates ・ x-extensions、根と欄に x-prompt、欄に x-relationship ・ x-derived-from ・ x-decided-by ・ x-published を書く。Concrete が足す x- は x-extensions に定義する。x-relationship の形は annotations が持つ。",
 "allOf": [
  {
   "$ref": "https://json-schema.org/draft/2020-12/schema"
  }
 ],
 "x-prompt": {
  "read": {
   "means": "Concrete を書く人が従う契約で、従っていれば基盤が中身を知らずに使える。",
   "when": "Concrete を書く前と、Concrete を照らした指摘を直すときに読む。"
  },
  "write": [
   {
    "id": "instance-path-and-kind",
    "rule": "instance を作るスキーマには x-instance-path を書き、根の properties に kind（const）を置く。",
    "why": "基盤は kind で instance の種類を判定する。",
    "test": "x-instance-path を持つスキーマの根に、kind の const があるかを見る。",
    "by": "machine"
   },
   {
    "id": "instance-schema-name",
    "rule": "instance を作るスキーマは、根の properties に $schema を置き、const にこのスキーマの $id を書く。",
    "why": "instance の $schema に、このスキーマの名前以外が書かれるのを、書いたその場で止める。",
    "test": "properties.$schema.const が $id と同じかを見る。",
    "by": "machine"
   },
   {
    "id": "prompt-per-unit",
    "rule": "書く単位（最上位のプロパティと、$defs の各形のプロパティ）ごとに description と x-prompt を書く。",
    "why": "Scaffold は、書く単位ごとの x-prompt を返す。",
    "test": "書く単位のどれにも description と x-prompt があるかを見る。",
    "by": "machine"
   },
   {
    "id": "no-prompt-on-leaf",
    "rule": "入れ子の奥の葉には x-prompt を書かない。",
    "why": "親の x-prompt が葉まで案内するので、葉にも書くと同じ決まりが2か所に並ぶ。",
    "test": "x-prompt を持つ葉の親が、同じ決まりを持っていないかを見る。",
    "by": "ai",
    "agent": "reviewer",
    "bad": "verification.passed[].option に x-prompt を書く。",
    "good": "verification.passed の x-prompt に、option の書き方も書く。"
   },
   {
    "id": "list-as-array",
    "rule": "並びになる値は、文字列に詰めず配列の型にする。",
    "why": "型で配列にしておけば、instance を書く人が文字列に詰めることができない。",
    "test": "区切りの記号で並びを書かせる文字列の欄が無いかを見る。",
    "by": "ai",
    "agent": "reviewer"
   },
   {
    "id": "core-keywords-closed",
    "rule": "x- で始まるキーは、Core の9つの x- か、このスキーマの x-extensions にある名前だけを使う。",
    "why": "知らない x- を通すと、検証されない宣言が合格に見え、保存の形（DB ・ テーブル）の宣言も通る。",
    "test": "x- で始まるキーが Core の9つか x-extensions にあるかを見る。",
    "by": "machine"
   },
   {
    "id": "term-by-ref",
    "rule": "欄が glossary の term を指すときは、標準の $ref で glossary の URN と $anchor を指す。",
    "why": "Semantic Schema Resolver は、$ref の指す先から欄の term を静的にたどる。",
    "test": "term を指す $ref の先が、閉じた一覧の glossary の $anchor かを見る。",
    "by": "machine"
   },
   {
    "id": "rule-agent",
    "rule": "どの決まりにも by を書き、by が ai なら agent に x-delegates の名前か、Core が予約した reviewer を書く。",
    "why": "Core の AI の rule は reviewer を使い、どの Concrete に割り当てるかは各 Concrete の x-delegates が決める。割り当てが無ければ unsupported。",
    "test": "by が ai の決まりの agent が、x-delegates の名前か reviewer かを見る。",
    "by": "machine"
   },
   {
    "id": "nested-fields",
    "rule": "入れ子の欄（items ・ allOf ・ 入れ子の properties）でも、x- と rule の決まりを守る。",
    "why": "本体は $dynamicAnchor を書かないので、入れ子の欄には本体の形の決まりが掛からず、Core が確かめる。",
    "test": "入れ子の欄の x- が Core の9つか x-extensions にあり、rule が $defs/rule の形かを見る。",
    "by": "machine"
   }
  ]
 },
 "type": "object",
 "required": [
  "$schema",
  "title",
  "description"
 ],
 "properties": {
  "$schema": {
   "type": "string",
   "format": "uri",
   "description": "従う Abstract の版",
   "x-prompt": {
    "read": {
     "means": "このスキーマが従う Abstract の版と作法の版で、閉じた一覧のどれかである。"
    },
    "write": [
     {
      "id": "closed-list",
      "rule": "Abstract の版の $id を書く。",
      "why": "基盤は閉じた一覧に無い $schema を取りに行かずに断る。",
      "test": "値が閉じた一覧のどれかと同じかを見る。",
      "by": "machine"
     }
    ]
   }
  },
  "$id": {
   "type": "string",
   "pattern": "^urn:semantic-schema-core:[a-z0-9][a-z0-9-]*:[a-z0-9][a-z0-9-]*:v[0-9]+$",
   "description": "スキーマの名前",
   "x-prompt": {
    "read": {
     "means": "instance が $schema で指す、このスキーマの名前である。",
     "parse": "urn:semantic-schema-core:<持ち主>:<種類>:v<版> の形で、版は v と数字である。"
    },
    "write": [
     {
      "id": "owner-kind-version",
      "rule": "urn:semantic-schema-core:<持ち主>:<種類>:v<版> の形で書く。持ち主は Core の一員なら core、文脈なら Skill か Agent の名前にする。",
      "why": "Semantic Schema Resolver は、Skill と Agent の置き場所から、この名前でスキーマを引く。",
      "test": "持ち主が core（Core の一員）か、このスキーマを持つ Skill か Agent のフォルダの名前かを見る。",
      "by": "machine"
     },
     {
      "id": "never-reuse",
      "rule": "公開した版の中身を変えるときは、版を上げた新しい名前で足す。",
      "why": "同じ名前で中身が変わると、前に書いた instance が別のスキーマで検査される。",
      "test": "公開した版の名前の中身が、公開した時と同じかを見る。",
      "by": "machine"
     }
    ]
   }
  },
  "title": {
   "type": "string",
   "minLength": 1,
   "description": "スキーマの名前",
   "x-prompt": {
    "read": {
     "means": "このスキーマが表すものの名前である。",
     "shown": "描画したページの題と、Concrete を照らした結果に出る。"
    },
    "write": [
     {
      "id": "noun",
      "rule": "instance が何であるかを、名詞で書く。",
      "why": "読む人は題だけで、何の instance かを判断する。",
      "test": "題が名詞で終わっているかを見る。",
      "by": "ai",
      "agent": "reviewer",
      "bad": "意思決定を記録するためのもの",
      "good": "意思決定の記録"
     }
    ]
   }
  },
  "description": {
   "type": "string",
   "minLength": 1,
   "description": "スキーマの説明",
   "x-prompt": {
    "read": {
     "means": "instance が何で、何を書かないかの説明である。"
    },
    "write": [
     {
      "id": "what-and-not",
      "rule": "instance が何であるかと、書かないもの（ほかのスキーマが持つもの）を書く。",
      "why": "書かないものが分からないと、ほかのスキーマと同じことを2か所に書く。",
      "test": "説明に、書かないものが1つ以上あるかを見る。",
      "by": "ai",
      "agent": "reviewer"
     }
    ]
   }
  },
  "x-instance-path": {
   "type": "string",
   "minLength": 1,
   "description": "このスキーマの instance を置く場所。名前の入る所は {id} のように書く（RFC 6570 のレベル1）",
   "x-prompt": {
    "read": {
     "means": "このスキーマの instance を置く場所である。",
     "parse": "{…} の部分は、id などの欄の値が入る所である。"
    },
    "write": [
     {
      "id": "level1-template",
      "rule": "名前の入る所を {欄の名前} にして、instance のファイルの置き場所を書く。",
      "why": "読む人とツールが、同じ置き場所に作る。",
      "test": "{…} の中が根の properties にある欄の名前で、ほかの部分が実際の置き場所と同じかを見る。",
      "by": "machine"
     },
     {
      "id": "only-for-instances",
      "rule": "instance を作らない部品のスキーマには書かない。",
      "why": "書くと、作られない instance の kind を探すことになる。",
      "test": "$defs だけを持つスキーマに x-instance-path が無いかを見る。",
      "by": "machine"
     }
    ]
   }
  },
  "x-instance-label": {
   "type": "string",
   "minLength": 1,
   "description": "他から指されたときと、変更を見せるときの instance の名前の型。{…} の中は欄の名前",
   "x-prompt": {
    "read": {
     "means": "instance を名前で見せるときの型である。",
     "shown": "他から指された所と、変更を見せる画面に出る。",
     "parse": "{…} の部分に、その欄の値が入る。"
    },
    "write": [
     {
      "id": "label-fields-exist",
      "rule": "{…} の中には、根の properties にある欄の名前だけを書く。",
      "why": "無い欄を書くと、名前を作れない。",
      "test": "{…} の中の名前が、根の properties にあるかを見る。",
      "by": "machine",
      "bad": "論点 {番号}",
      "good": "論点 {id}「{name}」"
     }
    ]
   }
  },
  "x-delegates": {
   "type": "object",
   "description": "任せる先。名前から、子のセッションに任せられる Concrete（role ・ Concrete の URN ・ モデル）を引く",
   "propertyNames": {
    "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
   },
   "additionalProperties": {
    "type": "object",
    "required": [
     "role",
     "concrete"
    ],
    "additionalProperties": false,
    "properties": {
     "role": {
      "type": "string",
      "minLength": 1,
      "description": "任せる役。review ・ writing ・ research など"
     },
     "concrete": {
      "type": "string",
      "pattern": "^urn:semantic-schema-core:[a-z0-9][a-z0-9-]*:[a-z0-9][a-z0-9-]*:v[0-9]+$",
      "description": "任せる先の Concrete の URN。Agent の定義もスキーマを持てば Concrete である"
     },
     "model": {
      "type": "string",
      "minLength": 1,
      "description": "任せるときのモデルの名前。書かなければ任せる先が決める"
     }
    }
   },
   "x-prompt": {
    "read": {
     "means": "このスキーマの rule が agent で指す名前と、その名前で任せる Concrete の一覧である。",
     "parse": "Core の AI の rule は reviewer を使い、どの Concrete に割り当てるかは各 Concrete の x-delegates が決める。割り当てが無ければ unsupported。"
    },
    "write": [
     {
      "id": "not-self",
      "rule": "このスキーマ自身の $id を concrete に書かない。",
      "why": "親は自分自身を任せる先に載せない。",
      "test": "どの concrete も、このスキーマの $id と違うかを見る。",
      "by": "machine"
     }
    ]
   }
  },
  "x-extensions": {
   "type": "object",
   "description": "Concrete が足す x- の定義。名前から、値の形 ・ 説明 ・ prompt ・ 公開するか（published）を引く",
   "propertyNames": {
    "pattern": "^x-[a-z0-9-]+$"
   },
   "additionalProperties": {
    "type": "object",
    "required": [
     "schema",
     "description",
     "prompt"
    ],
    "additionalProperties": false,
    "properties": {
     "schema": {
      "$ref": "https://json-schema.org/draft/2020-12/schema",
      "description": "x- の値の形（JSON Schema）。$ref の指す先にしない"
     },
     "description": {
      "type": "string",
      "minLength": 1
     },
     "prompt": {
      "$ref": "#/$defs/prompt",
      "description": "この x- の読み方と書き方のプロンプト（x-prompt と同じ形）。判定はその write に rule として書く"
     },
     "published": {
      "type": "boolean",
      "description": "true のとき、この x- の定義を他の文脈へ見せる"
     }
    }
   },
   "x-prompt": {
    "read": {
     "means": "このスキーマが足した x- の、値の形 ・ 意味 ・ 書き方と判定の決まりである。"
    },
    "write": [
     {
      "id": "no-core-names",
      "rule": "Core の9つの x- と同じ名前を使わない。",
      "why": "Core の x- とぶつかると、どちらの意味で読むかが決まらない。",
      "test": "名前が Core の9つと重なっていないかを見る。",
      "by": "machine"
     },
     {
      "id": "no-ref-into-extensions",
      "rule": "x-extensions の中の schema を、$ref の指す先にしない。",
      "why": "知らないキーワードの中にある指す先は、JSON Schema の実装ごとに振る舞いが決まっていない。",
      "test": "どの $ref も x-extensions の中を指していないかを見る。",
      "by": "machine"
     }
    ]
   }
  },
  "x-prompt": {
   "$ref": "#/$defs/prompt"
  },
  "properties": {
   "$ref": "#/$defs/fields"
  },
  "$defs": {
   "type": "object",
   "additionalProperties": {
    "$ref": "#/$defs/shape"
   }
  }
 },
 "if": {
  "required": [
   "x-instance-path"
  ]
 },
 "then": {
  "required": [
   "properties",
   "$id"
  ],
  "properties": {
   "properties": {
    "required": [
     "kind",
     "$schema"
    ],
    "properties": {
     "kind": {
      "required": [
       "const"
      ]
     },
     "$schema": {
      "required": [
       "const"
      ]
     }
    }
   }
  }
 },
 "$defs": {
  "shape": {
   "type": "object",
   "description": "$defs の形1つ。プロパティを持つなら、その書く単位に説明と案内を求める",
   "properties": {
    "properties": {
     "$ref": "#/$defs/fields"
    }
   }
  },
  "fields": {
   "type": "object",
   "description": "書く単位の並び",
   "properties": {
    "$schema": true
   },
   "additionalProperties": {
    "$ref": "#/$defs/field"
   }
  },
  "field": {
   "type": "object",
   "description": "書く単位1つ。欄に書く Core の x- は x-prompt ・ x-relationship ・ x-derived-from ・ x-decided-by ・ x-published の5つ",
   "required": [
    "description",
    "x-prompt"
   ],
   "properties": {
    "description": {
     "type": "string",
     "minLength": 1
    },
    "x-prompt": {
     "$ref": "#/$defs/prompt"
    },
    "x-relationship": {
     "$ref": "#/$defs/relationship"
    },
    "x-derived-from": {
     "$ref": "#/$defs/derived"
    },
    "x-decided-by": {
     "$ref": "#/$defs/decided"
    },
    "x-published": {
     "$ref": "#/$defs/published"
    }
   }
  },
  "relationship": {
   "$ref": "urn:semantic-schema-core:core:annotations:v1#/$defs/relationship",
   "description": "x-relationship。この欄が指す instance の種類。to は Concrete の URN で、指す先の instance が在ることを検査する",
   "x-prompt": {
    "read": {
     "means": "この欄の値が、to の種類の instance の id を指すことの宣言である。"
    },
    "write": [
     {
      "id": "target-exists",
      "rule": "to には、閉じた一覧か公開された版にある Concrete の URN を書く。",
      "why": "指す先の種類が引けないと、instance が在るかを確かめられない。",
      "test": "to の URN が引けて、値の指す instance が在るかを見る。",
      "by": "machine"
     }
    ]
   }
  },
  "derived": {
   "type": "object",
   "description": "x-derived-from。この欄の値を、何からどう導くか（rules ・ otherwise ・ declared）。依存は rules の when のキーから引ける",
   "required": [
    "rules",
    "otherwise"
   ],
   "additionalProperties": false,
   "properties": {
    "rules": {
     "type": "array",
     "minItems": 1,
     "description": "上から当て、最初に当たった決まりの then が導出値になる",
     "items": {
      "type": "object",
      "required": [
       "when",
       "then"
      ],
      "additionalProperties": false,
      "properties": {
       "when": {
        "type": "object",
        "minProperties": 1
       },
       "then": {
        "type": [
         "string",
         "number",
         "boolean"
        ]
       }
      }
     }
    },
    "otherwise": {
     "type": [
      "string",
      "number",
      "boolean"
     ],
     "description": "どの決まりにも当たらないときの導出値"
    },
    "declared": {
     "type": "string",
     "minLength": 1,
     "description": "導出値と比べる、同じオブジェクトの中のプロパティの名前"
    }
   },
   "x-prompt": {
    "read": {
     "means": "ほかの欄の答えから、この欄の値を導く決まりである。",
     "parse": "rules を上から見て最初に当たった then を導出値とし、どれにも当たらなければ otherwise を導出値とする。"
    },
    "write": [
     {
      "id": "only-mechanical",
      "rule": "答えの組み合わせから、値を機械的に決める決まりがあるときに書く。",
      "why": "人の判断が入る値は、決まりで導けない。",
      "test": "答えの組み合わせから、値が1つに決まるかを見る。",
      "by": "ai",
      "agent": "reviewer"
     }
    ]
   }
  },
  "decided": {
   "const": "human",
   "description": "x-decided-by。\"human\" のとき、この欄の値を決めるのは人である（決定権）",
   "x-prompt": {
    "read": {
     "means": "この欄の値は人が決め、人の入口から来たものでなければならない、という宣言である。",
     "when": "AI が instance を書く前と、変更を取り込む前に読む。"
    },
    "write": [
     {
      "id": "human-entry-only",
      "rule": "AI はこの欄の値を書き写してよいが、人の入口から来た値と違う値にしない。",
      "why": "人の入口を通らずに変えた変更は、取り込めない理由に出る。",
      "test": "変更の記録で、この欄が人の入口を通らずに変わっていないかを見る。",
      "by": "machine"
     }
    ]
   }
  },
  "published": {
   "type": "boolean",
   "description": "x-published。true のとき、この欄を他の文脈へ見せる。版は $id の v<版> が表す"
  },
  "prompt": {
   "type": "object",
   "description": "x-prompt。read は値の読み方を観点ごとに、write は書くときの決まり（rule）を1件ずつ持つ",
   "required": [
    "read",
    "write"
   ],
   "additionalProperties": false,
   "properties": {
    "read": {
     "$ref": "#/$defs/reading"
    },
    "write": {
     "type": "array",
     "minItems": 1,
     "items": {
      "$ref": "#/$defs/rule"
     }
    }
   }
  },
  "reading": {
   "type": "object",
   "description": "値の読み方。観点ごとに1文",
   "required": [
    "means"
   ],
   "additionalProperties": false,
   "properties": {
    "means": {
     "$ref": "#/$defs/sentence",
